sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-35: a CHECK_IN inspection completes the trip (FLEET - Validate Check-in still applies)
    var res = new GlideRecord('x_1850693_enterp_0_reservation');
    if (!res.get(current.getValue('reservation')) || res.getValue('reservation_state') != 'ACTIVE') {
        return;
    }
    res.setValue('check_in_odometer', current.getValue('odometer_reading'));
    res.setValue('reservation_state', 'COMPLETED');
    if (res.update()) {
        gs.addInfoMessage('Reservation ' + res.getValue('number') + ' checked in and completed.');
    }
    if (current.getValue('external_damage_notes')) {
        var url = 'x_1850693_enterp_0_damage.do?sys_id=-1&sysparm_query=' + encodeURIComponent('reservation=' +
            res.getUniqueValue() + '^vehicle=' + current.getValue('vehicle') + '^description=' + current.getValue('external_damage_notes'));
        gs.addInfoMessage('Damage was noted at check-in. <a href="' + url + '">Create a Damage record</a>.');
    }
})(current, previous);
